const row = $input.first()?.json || {};
function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
}
function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) {
  return sql(JSON.stringify(value ?? {})) + '::jsonb';
}
if (row.ok === false || row.ok === 'f') {
  return [{ json: { query: `SELECT false AS ok, ${sql(row.error || 'Image generation was not submitted.')} AS error;` } }];
}
const job = parse(row.job, null);
const generation = parse(row.generation, null);
if (!job || !generation) {
  return [{ json: { query: `SELECT false AS ok, ${sql('Generation submission did not return job metadata.')} AS error;` } }];
}
const promptPack = generation.promptPack || job.promptPack || {};
const referenceImages = Array.isArray(promptPack.referenceImages) ? promptPack.referenceImages : [];
const primaryReference = referenceImages[0] || null;
const referenceImage = primaryReference
  ? {
      contractVersion: 'comfy-reference-image-v1',
      assetId: primaryReference.assetId || null,
      minioBucket: primaryReference.minioBucket || primaryReference.bucket || null,
      minioObjectPath: primaryReference.minioObjectPath || primaryReference.objectPath || null,
      publicUrl: primaryReference.publicUrl || primaryReference.url || null,
      comfyInputName: primaryReference.comfyInputName || null,
      comfyLoadable: Boolean(primaryReference.comfyInputName),
      source: primaryReference.source || 'prompt-pack-reference-images'
    }
  : null;
let gateway;
try {
  gateway = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ai-gateway:8095/comfy/publication-submit',
    headers: {
      'Content-Type': 'application/json',
      'X-Request-Id': `publication-comfy-${job.publicationJobId}`
    },
    body: {
      job,
      promptPack,
      generationJobId: generation.generationJobId,
      referenceImage,
      dryRun: false
    },
    json: true,
    timeout: 120000
  });
} catch (error) {
  gateway = { ok: false, error: error?.message || 'Comfy Cloud gateway request failed.' };
}
const providerPromptId = gateway?.promptId || gateway?.response?.prompt_id || gateway?.response?.promptId || null;
const providerPayload = {
  provider: 'comfy-cloud',
  providerRequestId: gateway?.requestId || null,
  providerPromptId,
  providerResponse: gateway?.response || null,
  providerStatus: gateway?.ok ? 'submitted' : 'submission_failed',
  providerSubmittedAt: new Date().toISOString(),
  patched: gateway?.patched || null,
  gateway
};
const generationStatus = gateway?.ok ? 'running' : 'failed';
const publicationStatus = gateway?.ok ? 'generating' : 'failed';
const eventType = gateway?.ok ? 'generation-submitted' : 'generation-submit-failed';
const errorMessage = gateway?.ok ? null : (gateway?.error || 'Comfy Cloud submission failed.');
const query = `
CREATE TABLE IF NOT EXISTS publication_job_events (
  event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  publication_job_id uuid NOT NULL REFERENCES publication_jobs(publication_job_id) ON DELETE CASCADE,
  event_type text NOT NULL,
  event_payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
WITH updated_generation AS (
  UPDATE generation_jobs
  SET
    status = ${sql(generationStatus)},
    result_payload = COALESCE(result_payload, '{}'::jsonb) || ${sqlJson(providerPayload)},
    error_message = ${sql(errorMessage)},
    failed_at = CASE WHEN ${sql(generationStatus)} = 'failed' THEN now() ELSE failed_at END,
    updated_at = now()
  WHERE job_id = ${sql(generation.generationJobId)}::uuid
  RETURNING *
), updated_publication AS (
  UPDATE publication_jobs pj
  SET
    status = ${sql(publicationStatus)},
    error_message = ${sql(errorMessage)},
    updated_at = now(),
    metadata = COALESCE(pj.metadata, '{}'::jsonb) || jsonb_build_object(
      'generationJobId', ${sql(generation.generationJobId)}::uuid,
      'generationProviderStatus', ${sql(providerPayload.providerStatus)},
      'generationProviderPromptId', ${sql(providerPromptId)},
      'generationProviderSubmittedAt', now()
    )
  WHERE pj.publication_job_id = ${sql(job.publicationJobId)}::uuid
  RETURNING *
), event AS (
  INSERT INTO publication_job_events (publication_job_id, event_type, event_payload)
  VALUES (${sql(job.publicationJobId)}::uuid, ${sql(eventType)}, ${sqlJson(providerPayload)})
  RETURNING *
)
SELECT
  ${gateway?.ok ? 'true' : 'false'} AS ok,
  ${sql(errorMessage)} AS error,
  (SELECT row_to_json(updated_publication) FROM updated_publication) AS job,
  (SELECT jsonb_build_object(
    'generationJobId', job_id,
    'avatar', avatar,
    'scene', scene,
    'assetType', asset_type,
    'platform', platform,
    'status', status,
    'runMode', run_mode,
    'startedAt', started_at,
    'provider', 'comfy-cloud',
    'providerPromptId', result_payload->>'providerPromptId',
    'providerStatus', result_payload->>'providerStatus',
    'providerRequestId', result_payload->>'providerRequestId',
    'providerResponse', result_payload->'providerResponse',
    'patched', result_payload->'patched',
    'promptPack', prompt_pack
  ) FROM updated_generation) AS generation;
`;
return [{ json: { query } }];

const row = $input.first()?.json || {};
function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
}
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, submitted: false, error: row.error || 'Comfy Cloud submission failed.' } }];
}
return [{ json: { ok: true, submitted: true, job: parse(row.job, null), generation: parse(row.generation, null) } }];
